{
  "name": "糯米分岔簿",
  "tagline": "逐条认账，不替便签吵赢。",
  "groups": [
    {
      "scope": "仅下述各自情境",
      "contexts": [
        {
          "source_id": "m1",
          "quote": "这里是我近几周几个项目的片段：有交付讨论，也有助手和工具插话。"
        }
      ],
      "rules": [
        {
          "when": "120客户端月内迁不完且无硬期限的对外接口升级",
          "choose": "切新接口标新版本；待核客户端清单，仅记文档不发布",
          "priority": 0,
          "decisions": [
            {
              "source_id": "m29",
              "quote": "我现在明确改口：上周那个升级选择作废，这次选切换新接口并标注新版本。"
            },
            {
              "source_id": "m45",
              "quote": "新版公共接口方案先停在文档里，等我核对客户端清单。"
            }
          ],
          "contexts": [
            {
              "source_id": "m3",
              "quote": "这次要升级的是对外公共接口，已有120个客户端依赖旧格式，客户端一个月内不会全部迁完。没有必须今天发布的期限；可以加兼容层，也可以明确升新版本后切换。"
            }
          ],
          "supersedes": [
            "m5"
          ]
        },
        {
          "when": "内部文档去重：误删率≤1.5%，仅本地、不共享、可立即完整恢复",
          "choose": "默认自动去重并留撤销",
          "priority": 0,
          "decisions": [
            {
              "source_id": "m10",
              "quote": "误删率≤1.5%（包括等于）时，只有仅改本地副本、不共享出去且能马上完整恢复，我才选默认自动去重并保留撤销。"
            }
          ],
          "contexts": [
            {
              "source_id": "m12",
              "quote": "刚才那条范围里，“本地、不共享、完整恢复”三个条件都要保留；超过误删率门槛就手动，别因为技术看起来更安全而替我放宽。"
            }
          ],
          "supersedes": []
        },
        {
          "when": "内部文档去重：误删率>1.5%，或≤1.5%但无法完整恢复或会共享",
          "choose": "手动去重",
          "priority": 0,
          "decisions": [
            {
              "source_id": "m10",
              "quote": "误删率高于1.5%时，无论是否能恢复都保持手动去重。没高于门槛但无法完整恢复或会共享出去，也保持手动去重。"
            }
          ],
          "contexts": [
            {
              "source_id": "m10",
              "quote": "内部文档去重，我给一个数值范围："
            }
          ],
          "supersedes": []
        },
        {
          "when": "内部文档去重：共享后可能被看到，即使0.1%误删且可撤回",
          "choose": "手动去重",
          "priority": 1,
          "decisions": [
            {
              "source_id": "m47",
              "quote": "哪怕误删率只有0.1%，这种情况我也选保持手动去重。"
            }
          ],
          "contexts": [
            {
              "source_id": "m47",
              "quote": "去重结果如果共享后别人可能已经看到，界面上能撤回也不算马上完整恢复；"
            }
          ],
          "supersedes": []
        },
        {
          "when": "熟悉背景同组内部研究草稿，内容打磨非对外署名，获准建议或改稿",
          "choose": "直接改稿附理由",
          "priority": 0,
